#[test]
fn fixtures_are_removed_when_a_test_ends() {
    // The agent guide requires generated fixtures to be cleaned up. Proven
    // rather than asserted in a comment.
    let dir;
    {
        let fx = Fixtures::new("cleanup");
        dir = fx.0.clone();
        std::fs::write(fx.path("x.bin"), b"data").unwrap();
        assert!(dir.exists());
    }
    assert!(!dir.exists(), "fixture directory must be removed on drop");
}
